head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFooterData]<br/>Footer Cell 정보를 사용하여 특정 Footer Cell 의 데이터를 반환합니다.",
    "validation" : [
        "footerId(필수) 파라미터로 데이터를 조회할 Footer Cell 의 인덱스값을 설정할 수 있어야 합니다. (인덱스는 0 부터 시작)",
        "display(선택) 파라미터가 'displayData' 이면 displayFormat, displayFormatter 등 Display 포맷이 적용된 값을 반환하고, 그 외 모든 값(undefined 포함)이면 원본값을 반환해야 합니다.",
        "display(선택) 파라미터를 생략하면 기본값 undefined 로 동작하여 원본값을 반환해야 합니다.",
        "inputType='expression' 이면 expression 수식을 재실행하여 최신값을 반환해야 합니다.",
        "파라미터가 유효하지 않으면 undefined 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // Footer Cell 데이터/포맷 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="Footer Cell 인덱스 0: ft1(text, 합계) / 1: ft2(number, 원본 23456 + displayFormat #,###) / 2: ft3(expression, 1000+2345) / 3: ft4(text, footer4)"', '', 'label1');

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody + Footer 1행, Footer Cell 데이터/포맷 다양화)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getFooterData 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="구분"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="금액"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="수식"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    // index 0 : 일반 text Footer Cell
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    // index 1 : 숫자값 + displayFormat (display="displayData" 검증용, 원본 23456 -> "23,456")
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" displayFormat="#,###" id="ft2" value="23456"></w2:column>';
    // index 2 : inputType="expression" (expression 수식 재실행 검증용)
    strTarget += '<w2:column width="130" style="" inputType="expression" id="ft3" expression="1000 + 2345"></w2:column>';
    // index 3 : 일반 text Footer Cell
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_getFooterData_onclick = function () {
    // footerId 는 인덱스(Number) 로 전달
    let footerId = Number(par_footerId.getValue());

    // display(선택) : 빈 값이면 생략(1-인자 호출 -> 기본값 undefined), "displayData" 면 2-인자 호출
    let display = par_display.getValue();

    let rtn;
    if (display === '') {
        // display 파라미터 생략 (기본값 undefined 로 동작)
        rtn = target1.getFooterData(footerId);
    } else {
        rtn = target1.getFooterData(footerId, display);
    }

    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }

    let callStr = (display === '') ? 'getFooterData(' + footerId + ')' : "getFooterData(" + footerId + ", '" + display + "')";
    wf_body_bottom.getObj("scwin").setReturnValue(callStr + " : " + rtn);
}
